import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )
    records = list(reader)

    width = 2

    def is_numeric_record(record):
        if len(record) != width or not record:
            return False
        try:
            for value in record:
                if value.strip() == "":
                    return False
                float(value)
            return True
        except ValueError:
            return False

    header_index = None
    for index, record in enumerate(records):
        if len(record) != width or is_numeric_record(record):
            continue
        if any(is_numeric_record(following) for following in records[index + 1:index + 2]):
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if len(record) == width),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    columns = list(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = []
    for record in records[header_index + 1:]:
        rows.append(list(record) + [""] * max(0, width - len(record)))

    return {"columns": columns, "rows": rows}
